// VideoModal Component
const VideoModal = ({ video, onClose }) => {
  const videoRef = useRef(null);
  
  useEffect(() => {
    // Focus trap
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    document.body.style.overflow = 'hidden';
    
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'auto';
    };
  }, [onClose]);
  
  useEffect(() => {
    // Auto-play when modal opens
    if (videoRef.current) {
      videoRef.current.play().catch(err => {
        console.log('Autoplay prevented:', err);
      });
    }
  }, []);
  
  return (
    <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
      <div className="relative bg-white rounded-lg w-full max-w-4xl overflow-hidden shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="absolute top-4 right-4 z-10">
          <button
            onClick={onClose}
            className="bg-black bg-opacity-50 text-white rounded-full p-2 hover:bg-opacity-70 transition-all"
            aria-label="Close modal"
          >
            <FaTimes size={20} />
          </button>
        </div>
        
        <div className="p-2">
          <div className="aspect-w-16 aspect-h-9 w-full overflow-hidden">
            <video
              ref={videoRef}
              className="w-full h-full object-contain"
              controls
              preload="metadata"
              src={video.videoUrl}
            >
              Your browser does not support the video tag.
            </video>
          </div>
          
          <div className="p-6">
            <h3 className="text-2xl font-bold mb-2">{video.title}</h3>
            <p className="text-gray-700">{video.description}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

